'use strict';
let shopState={items:{},free:[],mode:'kits'},shopFilter='all',catalogRows=[];
async function loadCatalog(){catalogRows=await C.catalog();for(const row of catalogRows){const list=D.catalog[row.category],i=list.findIndex(x=>x.name===row.name),item={...row.data,name:row.name};if(i>=0)list[i]={...list[i],...item};else list.push(item);}if(window.ND_CATALOG_V2)D.catalog=window.ND_CATALOG_V2.normalizeCatalog(D.catalog);}
function kitSelected(k){const entries=Object.entries(shopState.items).filter(([id])=>!shopState.free.includes(id));return k.ready&&entries.length===k.rows.length&&k.rows.every(x=>shopState.items[x.key]===1);}
function shopQuote(){return ND_SHOP.quote(shopState,D);}
function shopChange(fn){const old=E.clone(shopState);try{fn();shopQuote();rememberWizard();showEquipment();}catch(e){shopState=old;showEquipment();portalError(e);}}
function shopDetail(x){modal(x.displayName||x.name,`${catalogIcon(x,'catalog-detail-icon')}<p>${esc(x.description)}</p><p>${esc(shopParams(x))}</p><button id="shop-detail-close">Закрыть</button>`);$('#shop-detail-close').onclick=closeModal;}
function shopParams(x){return [x.damage!==undefined?'Урон '+x.damage:'',x.range?'Дальность '+x.range:'',x.slot||'',x.armor!==undefined?'Броня '+x.armor:'',x.slots?'Хром '+x.slots:'',x.type||''].filter(Boolean).join(' · ');}
function showEquipment(){portalView='wizard';let q;try{q=shopQuote();}catch(e){portalShell('Проверь оснащение','Каталог изменился.',`<p>${esc(e.message)}</p><button id="reset-shop">Очистить предварительное оснащение</button>`);$('#reset-shop').onclick=()=>{shopState={items:{},free:[],mode:'kits'};rememberWizard();showEquipment();};return;}const all=ND_SHOP.all(D),kits=ND_SHOP.kits(D);portalShell('С чем ты войдёшь в город?','04 / Оснащение · готовый комплект или собственная сборка. Выбор не задаёт класс персонажа.',`<div class="shop-budget" role="status">Бюджет: <b>2 000</b> <span>Потрачено: <b>${q.total}</b></span><span>Осталось: <b>${q.left}</b></span></div><div class="library-toolbar"><button id="shop-kits" ${shopState.mode==='kits'?'class="yellow"':''}>Готовый комплект</button><button id="shop-custom" ${shopState.mode==='custom'?'class="yellow"':''}>Собрать самостоятельно</button></div>${shopState.mode==='kits'?`<div class="kit-grid">${kits.map(k=>`<article class="panel kit-card ${kitSelected(k)?'is-selected':''}"><div class="kit-portrait"><img src="assets/${k.id}.jpg" alt="${esc(k.name)}" loading="lazy"></div><button type="button" class="kit-select" data-kit="${k.id}" aria-pressed="${kitSelected(k)}" ${!k.ready||k.price>2000?'disabled':''}><span>${kitSelected(k)?'✓ Комплект выбран':'Выбрать комплект'}</span><span aria-hidden="true">${kitSelected(k)?'●':'↗'}</span></button><div class="kit-body"><h2>${esc(k.name)}</h2><p>${esc(k.description)}</p><ul>${k.rows.map(x=>`<li>${esc(x.displayName||x.name)} — ${x.price}</li>`).join('')}</ul>${k.id==='netrunner'?'<p>Два различных базовых Червя — бесплатно</p>':''}<p>${k.ready?`Стоимость: <b>${k.price}</b> · Остаток: <b>${2000-k.price}</b>`:'Ожидает параметров недостающего оружия в справочнике'}</p></div></article>`).join('')}</div>`:`<div class="shop-filters"><button data-shop-filter="all" ${shopFilter==='all'?'class="yellow"':''}>Все</button>${Object.entries(ND_SHOP.groups).map(([id,name])=>`<button data-shop-filter="${id}" ${shopFilter===id?'class="yellow"':''}>${name}</button>`).join('')}</div><div class="shop-items">${all.filter(x=>ND_SHOP.allowed(x)&&(shopFilter==='all'||(x.shopCategory||x.cat)===shopFilter)).map(x=>`<article class="panel shop-product ${shopState.items[x.key]?'is-selected':''}"><div class="product-top"><span class="eyebrow">${esc(ND_SHOP.groups[x.shopCategory||x.cat]||labels[x.cat])}</span><span class="product-price">${x.price} <small>эдди</small></span></div>${catalogIcon(x)}<h3>${esc(x.displayName||x.name)}</h3><p class="product-params">${esc(shopParams(x))}</p><p class="product-description">${esc(x.description)}</p><div class="product-status">${shopState.items[x.key]?`✓ В корзине: ${shopState.items[x.key]} шт.`:'Доступно на старте'}</div><div class="product-actions">${!shopState.items[x.key]||x.cat==='consumables'?`<button class="product-add" data-shop-add="${esc(x.key)}" ${q.left<x.price?'disabled':''}>${shopState.items[x.key]?'+ Добавить ещё':'+ Добавить'}</button>`:''}${shopState.items[x.key]?`<button class="product-remove" data-shop-remove="${esc(x.key)}" aria-label="Убрать из корзины: ${esc(x.displayName||x.name)}">Убрать из корзины</button>`:''}<button data-shop-detail="${esc(x.key)}">Подробнее</button></div></article>`).join('')}</div>`}<section class="panel shop-cart"><header class="equipment-heading"><div><span class="eyebrow">СТАРТОВЫЕ ПОКУПКИ</span><h2>Корзина</h2></div><span class="equipment-total">${q.rows.reduce((n,x)=>n+x.quantity,0)} шт. <b>${q.total} эдди</b></span></header>${q.rows.length?`<div class="cart-list">${q.rows.map(x=>`<div class="cart-row"><div class="cart-item"><span class="eyebrow">${esc(ND_SHOP.groups[x.shopCategory||x.cat]||labels[x.cat])}</span><strong>${esc(x.displayName||x.name)}</strong>${shopState.free.includes(x.key)?'<span class="cart-bonus">В комплекте с декой</span>':''}</div><div class="cart-quantity">${x.cat==='consumables'?`<label><span>Количество</span><input aria-label="Количество: ${esc(x.displayName||x.name)}" type="number" min="1" max="999" value="${x.quantity}" data-shop-qty="${esc(x.key)}"></label>`:'<span class="micro">1 шт.</span>'}</div><div class="cart-price">${shopState.free.includes(x.key)?'Бесплатно':`${x.price*x.quantity} <small>эдди</small>`}</div><button class="cart-remove" aria-label="Убрать: ${esc(x.displayName||x.name)}" data-shop-remove="${esc(x.key)}">Убрать</button></div>`).join('')}</div>`:'<p class="cart-empty">Пока пусто. Выбери комплект или добавь предметы из каталога — весь неиспользованный бюджет останется у персонажа.</p>'}</section>${q.deck?`<section class="panel worm-panel"><header class="equipment-heading"><div><span class="eyebrow">СТАРТОВЫЙ СОФТ / НЕЙРО-ДЕКА</span><h2>Два Червя на выбор</h2></div><span class="worm-counter ${shopState.free.length===2?'complete':''}" role="status">Выбрано <b>${shopState.free.length} из 2</b></span></header><p class="worm-intro">Выбери две разные программы бесплатно. Описания и параметры — из общего справочника.</p><div class="worm-grid">${all.filter(x=>x.cat==='programs'&&ND_SHOP.allowed(x)).map(x=>`<label class="worm-choice ${shopState.free.includes(x.key)?'is-selected':''}"><input type="checkbox" data-free-worm="${esc(x.key)}" ${shopState.free.includes(x.key)?'checked':''} ${shopState.free.length===2&&!shopState.free.includes(x.key)?'disabled':''}><span class="worm-content"><span class="worm-title">${esc(x.displayName||x.name)}</span><span class="worm-description">${esc(x.description)}</span><span class="worm-parameters">${x.target?`<span><b>Цель</b>${esc(x.target)}</span>`:''}${x.difficulty?`<span><b>Сложность</b>${esc(x.difficulty)}</span>`:''}</span><span class="worm-status">${shopState.free.includes(x.key)?'✓ Программа выбрана':'Включить в комплект'}</span></span></label>`).join('')}</div><p class="hint worm-footnote">Бонус доступен только при создании. Чтобы заменить программу, сначала сними выбор с одной из двух.</p></section>`:''}<div class="wizard-actions"><button id="equipment-back">← Назад</button><button id="equipment-next" class="yellow">Создать персонажа</button></div>`);
$('#shop-kits').onclick=()=>{shopState.mode='kits';rememberWizard();showEquipment();};$('#shop-custom').onclick=()=>{shopState.mode='custom';rememberWizard();showEquipment();};$('#equipment-back').onclick=goBack;$('#equipment-next').onclick=finishCharacter;
document.querySelectorAll('[data-kit]').forEach(b=>b.onclick=()=>shopChange(()=>{const k=kits.find(x=>x.id===b.dataset.kit);if(kitSelected(k))return;shopState.items=Object.fromEntries(k.rows.map(x=>[x.key,1]));shopState.free=[];}));document.querySelectorAll('[data-shop-filter]').forEach(b=>b.onclick=()=>{shopFilter=b.dataset.shopFilter;showEquipment();});document.querySelectorAll('[data-shop-add]').forEach(b=>b.onclick=()=>shopChange(()=>{const k=b.dataset.shopAdd;shopState.items[k]=(shopState.items[k]||0)+1;}));document.querySelectorAll('[data-shop-detail]').forEach(b=>b.onclick=()=>shopDetail(all.find(x=>x.key===b.dataset.shopDetail)));document.querySelectorAll('[data-shop-qty]').forEach(b=>b.onchange=()=>shopChange(()=>{shopState.items[b.dataset.shopQty]=+b.value;}));document.querySelectorAll('[data-shop-remove]').forEach(b=>b.onclick=()=>shopChange(()=>{const k=b.dataset.shopRemove;delete shopState.items[k];shopState.free=shopState.free.filter(id=>id!==k);if(all.find(x=>x.key===k).name.includes('Third-Eye')){for(const id of shopState.free)delete shopState.items[id];shopState.free=[];}}));document.querySelectorAll('[data-free-worm]').forEach(b=>b.onchange=()=>shopChange(()=>{const id=b.dataset.freeWorm;if(b.checked){shopState.free.push(id);shopState.items[id]=1;}else{shopState.free=shopState.free.filter(x=>x!==id);delete shopState.items[id];}}));}
/* Catalog V2 keeps legacy storage keys stable while exposing typed records. */
let catalogClass='all',catalogQuery='',catalogFilter='all';
const cv2=()=>window.ND_CATALOG_V2;
const catalogFields={
 ranged_weapon:[['damage','Базовый урон'],['rangeMin','Мин. дальность, гексы'],['rangeMax','Макс. дальность, гексы'],['hands','Хват, рук']],
 melee_weapon:[['damage','Урон'],['reach','Досягаемость, гексы'],['hands','Хват, рук'],['bodyRequirement','Требование к Телу']],
 throwable:[['rangeMax','Дальность, гексы'],['area','Зона / форма','text'],['damage','Урон (если есть)'],['duration','Длительность','text'],['uses','Применений']],
 implant:[['chromeSlots','Слоты Хрома','equipment'],['placement','Место установки','equipmentText'],['activation','Пассивный / активный','activation'],['driveCost','Расход Драйва'],['duration','Длительность','text'],['cooldown','Перезарядка','text']],
 neurodeck:[['chromeSlots','Слоты Хрома','equipment'],['hackingBonus','Бонус Взлома','equipment'],['wormCapacity','Ёмкость Червей','equipment'],['demonCapacity','Ёмкость Демонов','equipment'],['defense','Защита / контр-ICE','text']],
 worm:[['target','Тип цели','text'],['difficulty','СЛ / условие','text'],['rangeMax','Дальность, гексы'],['damage','Урон'],['duration','Длительность','text']],
 heavy_demon:[['target','Тип цели','text'],['difficulty','СЛ / условие','text'],['activationCost','Расход активации','text'],['rangeMax','Дальность, гексы'],['damage','Урон'],['duration','Длительность','text']],
 clothing_armor:[['armor','Ячейки брони'],['penalties','Штрафы / заметность','text']],
 gadget:[['deviceType','Тип устройства','text'],['consumable','Расходуемый','bool'],['rangeMax','Дальность, гексы'],['area','Зона','text'],['charges','Заряды'],['duration','Длительность','text']],
 vehicle:[['vehicleType','Тип транспорта','text'],['durability','Прочность'],['armor','Броня'],['capacity','Вместимость'],['maneuverability','Манёвренность (если утверждена)','text'],['size','Размер','text'],['electronics','Электроника / уязвимости','text']],
 medicine:[['healing','Лечение / реанимация / анти-психоз','text'],['useTime','Время применения','text'],['difficulty','СЛ','text'],['limits','Лимиты / побочные эффекты','text']],
 stimulant:[['temporaryBonus','Временный эффект','text'],['duration','Длительность','text'],['action','Действие','text'],['frequency','Частота','text'],['withdrawal','Отходняк','text']],
 perk:[['specialization','Специализация','text'],['activation','Пассивный / активный','activation'],['action','Тип действия','text'],['driveCost','Драйв'],['riskCost','Риск'],['trigger','Триггер','text'],['duration','Длительность','text'],['limits','Ограничения','text']]
};
function catalogOptions(entries,value){return entries.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');}
function catalogTypeFields(x){return (catalogFields[x.classId]||[]).map(([key,label,type])=>{const equipment=['equipment','equipmentText','activation'].includes(type),v=equipment?x.equipment?.[key]:x.stats?.[key]??x[key];return `<label class="field"><span>${esc(label)}</span>${type==='activation'?`<select data-typed="${key}" data-store="equipment">${catalogOptions([['','Не задано'],['passive','Пассивный'],['active','Активный']],v||'')}</select>`:type==='bool'?`<input type="checkbox" data-typed="${key}" data-store="stats" ${v?'checked':''}>`:`<input data-typed="${key}" data-store="${equipment?'equipment':'stats'}" ${type==='text'||type==='equipmentText'?'type="text" maxlength="1000"':'type="number" min="0" max="1000000" step="1"'} value="${esc(v??'')}" placeholder="Не задано">`}</label>`;}).join('');}
function catalogEffectRow(e,index){const derived=e.type==='derived_modifier',targetType=derived?'derived':e.targetType||'skill';const ids=targetType==='attribute'?cv2().attributeIds:targetType==='skill'?cv2().skillIds:['max_hp','armor','chrome_capacity'];const names=targetType==='attribute'?D.attributes.map(x=>x.name):targetType==='skill'?D.skills.map(x=>x.name):['Макс. HP','Ячейки брони','Лимит Хрома'];return `<div class="catalog-effect" data-effect="${index}"><select data-effect-field="targetType" aria-label="Тип бонуса">${catalogOptions(derived?[['derived','Ресурс']]:[['attribute','Характеристика'],['skill','Навык']],targetType)}</select><select data-effect-field="targetId" aria-label="Цель бонуса">${catalogOptions(ids.map((id,i)=>[id,names[i]]),e.targetId)}</select><input data-effect-field="value" type="number" min="-100" max="100" step="1" required value="${esc(e.value??1)}" aria-label="Значение бонуса"><select data-effect-field="duration" aria-label="Состояние действия">${catalogOptions([['while_installed','Установлен'],['while_equipped','Экипирован'],['while_loaded','Загружен'],['while_learned','Изучен']],e.duration||'while_installed')}</select><button type="button" data-effect-remove="${index}" aria-label="Удалить бонус">×</button></div>`;}
function catalogVisibleRows(){return ND_SHOP.all(D).map(x=>({...cv2().normalizeItem(x,x.cat),cat:x.cat,key:x.key})).filter(x=>(catalogClass==='all'||(catalogClass==='unclassified'?!x.classId:x.classId===catalogClass))&&(catalogFilter!=='start'||x.startAllowed)&&(catalogFilter!=='archive'||x.archived)&&(catalogFilter==='archive'||!x.archived)&&(catalogFilter!=='incomplete'||!x.classId||x.economy?.price==null)&&[x.name,x.displayName,x.manufacturer].some(v=>String(v||'').toLocaleLowerCase('ru').includes(catalogQuery.toLocaleLowerCase('ru'))));}
function showCatalogAdmin(){if(!portalMaster){portalError(Error('Нужны права мастера'));return;}portalView='catalog';portalShell('Справочник','Единый каталог. Бонусы пересчитываются по актуальным эффектам; базовые значения и выданные деньги не изменяются.',`<div class="catalog-v2"><aside class="catalog-types"><button data-catalog-class="all">Все классы</button>${cv2().classes.map(c=>`<button data-catalog-class="${c.id}" ${catalogClass===c.id?'aria-current="page"':''}><small>${esc(c.group)}</small>${esc(c.label)} <span>${ND_SHOP.all(D).filter(x=>cv2().normalizeItem(x,x.cat).classId===c.id).length}</span></button>`).join('')}<button data-catalog-class="unclassified">Требует классификации</button></aside><section class="catalog-list"><div class="catalog-tools"><button id="catalog-new" class="yellow">+ Добавить</button><input id="catalog-search" type="search" placeholder="Имя или бренд" value="${esc(catalogQuery)}" aria-label="Поиск в каталоге"><select id="catalog-filter" aria-label="Фильтр каталога">${catalogOptions([['all','Все'],['start','На старте'],['archive','Архив'],['incomplete','Требует заполнения']],catalogFilter)}</select></div><div id="catalog-results"></div></section><aside id="catalog-editor" class="catalog-editor"><p class="hint">Выбери запись для редактирования</p></aside></div>`);$('#catalog-new').onclick=()=>catalogEdit();document.querySelectorAll('[data-catalog-class]').forEach(b=>b.onclick=()=>{catalogClass=b.dataset.catalogClass;showCatalogAdmin();});$('#catalog-search').oninput=e=>{catalogQuery=e.target.value;catalogRenderList();};$('#catalog-filter').onchange=e=>{catalogFilter=e.target.value;catalogRenderList();};catalogRenderList();}
function catalogRenderList(){const rows=catalogVisibleRows();$('#catalog-results').innerHTML=rows.map(x=>`<article class="catalog-list-row"><div>${catalogIcon(x)}<strong>${esc(x.displayName||x.name)}</strong><small>${esc(cv2().classes.find(c=>c.id===x.classId)?.label||'Требует классификации')} · ${x.economy?.price??'Не задано'} ${x.classId==='perk'?'ОО':'эдди'}</small><small>${esc(shopParams(x))}</small></div><div><button data-catalog-edit="${esc(x.key)}">Изменить</button><button data-catalog-copy="${esc(x.key)}">Дублировать</button><button data-catalog-archive="${esc(x.key)}">${x.archived?'Восстановить':'Архивировать'}</button></div></article>`).join('')||'<p class="hint">Записи не найдены</p>';const get=key=>rows.find(x=>x.key===key);document.querySelectorAll('[data-catalog-edit]').forEach(b=>b.onclick=()=>catalogEdit(get(b.dataset.catalogEdit)));document.querySelectorAll('[data-catalog-copy]').forEach(b=>b.onclick=()=>catalogEdit(get(b.dataset.catalogCopy),true));document.querySelectorAll('[data-catalog-archive]').forEach(b=>b.onclick=async()=>{const x=get(b.dataset.catalogArchive);try{await persistCatalog(x.cat,x.name,{...x,archived:!x.archived});showCatalogAdmin();}catch(e){portalError(e);}});}
async function persistCatalog(cat,name,data){if(!portalMaster)throw Error('Нужны права мастера');const row=catalogRows.find(x=>x.category===cat&&x.name===name);const r=await C.saveCatalog(cat,name,data,row?.revision);if(!r?.length)throw Error('Справочник изменён в другом окне. Обнови страницу.');await loadCatalog();}
function catalogEdit(item,duplicate=false){if(!portalMaster)return;let x=item?E.clone(item):{classId:catalogClass!=='all'&&catalogClass!=='unclassified'?catalogClass:'implant',effects:[],stats:{},equipment:{},economy:{price:null},availability:{}};if(duplicate){delete x.id;delete x.catalogId;delete x.legacy;x.name='';x.displayName=(x.displayName||item.name)+' — копия';}x.stats=x.stats||{};x.equipment=x.equipment||{};x.effects=x.effects||[];const editor=$('#catalog-editor');if(!editor)return;function draw(){editor.innerHTML=`<form id="catalog-form"><header><h2>${item&&!duplicate?'Изменить запись':'Новая запись'}</h2><button type="button" id="catalog-cancel">Отмена</button></header><div class="catalog-form-scroll"><fieldset><legend>Идентификация</legend><label class="field">Класс<select name="classId">${catalogOptions([['','Требует классификации'],...cv2().classes.map(c=>[c.id,c.label])],x.classId||'')}</select></label><label class="field">Технический ID<input readonly value="${esc(x.catalogId||x.id||'Будет назначен при сохранении')}"></label><label class="field">Название<input name="displayName" required maxlength="200" value="${esc(x.displayName||x.name||'')}"></label><label class="field">Подтип<input name="subtype" maxlength="200" value="${esc(x.subtype||'')}"></label><label class="field">Производитель<input name="manufacturer" maxlength="200" value="${esc(x.manufacturer||'')}"></label><label class="field">Описание<textarea name="description" maxlength="20000" rows="4">${esc(x.description||'')}</textarea></label></fieldset><fieldset><legend>Иконка предмета · 1:1</legend><div id="catalog-icon-preview">${catalogIcon(x,'catalog-icon-preview')}</div><p id="catalog-icon-kind" class="hint">${hasCustomCatalogIcon(x)?'Индивидуальная иконка':'Стандартная иконка класса'}</p><label class="field">Загрузить / заменить · JPG, PNG или WebP · до 10 МБ<input id="catalog-icon-file" type="file" accept="image/jpeg,image/png,image/webp"></label><button type="button" id="catalog-icon-remove" ${hasCustomCatalogIcon(x)?'':'hidden'}>Сбросить на стандартную</button><p id="catalog-icon-error" role="alert"></p></fieldset><fieldset><legend>Характеристики</legend><div class="catalog-typed-fields">${catalogTypeFields(x)}</div></fieldset><fieldset><legend>Постоянные бонусы</legend>${x.effects.map((e,i)=>e.type==='stat_modifier'?catalogEffectRow(e,i):'').join('')}<button type="button" id="effect-add">+ Добавить постоянный бонус</button></fieldset><fieldset><legend>Другие игровые эффекты</legend>${x.effects.map((e,i)=>e.type==='derived_modifier'?catalogEffectRow(e,i):'').join('')}<button type="button" id="derived-add">+ Добавить бонус ресурса</button>${x.effects.filter(e=>!['stat_modifier','derived_modifier'].includes(e.type)).map(e=>`<p class="hint">${esc(e.type)} · ${esc(e.description||e.rulesText||e.targetId||'Существующий эффект сохранён')}</p>`).join('')}<label class="field">Уникальные правила и условия<textarea name="rulesText" rows="5" maxlength="20000">${esc(x.rulesText||'')}</textarea></label><p class="hint">Условные и временные эффекты не превращаются в постоянные бонусы листа</p></fieldset>${x.classId==='perk'?`<fieldset><legend>Требования развития</legend><p class="hint">Проверяются базовые значения. Текстовые ограничения блокируют покупку до формализации Мастером.</p><label class="field">Требования (JSON)<textarea name="perkRequirements" rows="4">${esc(JSON.stringify(x.requirements??[],null,2))}</textarea></label><p class="hint">Пример: [{"kind":"skill","targetId":"shooting","minimum":2}]. kind: attribute / skill. ID цели совпадает с ID в бонусах.</p><label><input name="perkRepeatable" type="checkbox" ${x.repeatable?'checked':''}> Правила явно разрешают повторную покупку</label></fieldset>`:''}<fieldset><legend>Доступность</legend><label class="field">${x.classId==='perk'?'Стоимость, ОО':'Цена, эдди'}<input name="price" type="number" min="0" max="100000000" step="1" placeholder="Не задано" value="${esc(x.economy?.price??(x.classId==='perk'?x.cost:x.price)??'')}"></label>${x.classId!=='perk'?`<label><input type="checkbox" name="startAllowed" ${x.startAllowed||x.availability?.startAllowed?'checked':''}> Доступен при стартовой закупке</label>`:''}<label><input type="checkbox" name="archived" ${x.archived?'checked':''}> В архиве</label><label class="field">Ограничения<textarea name="restrictions" maxlength="2000">${esc(x.availability?.restrictions||'')}</textarea></label></fieldset></div><footer class="catalog-editor-actions"><button type="submit" class="yellow">Сохранить</button><p id="catalog-editor-error" role="alert"></p></footer></form>`;
const f=$('#catalog-form');let iconPending=false;$('#catalog-icon-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;iconPending=true;f.querySelector('[type=submit]').disabled=true;try{const value=await window.ND_PORTRAIT.crop(file,{kind:'item'});if(value){x.icon=value;$('#catalog-icon-preview').innerHTML=catalogIcon(x,'catalog-icon-preview');$('#catalog-icon-kind').textContent='Индивидуальная иконка';$('#catalog-icon-remove').hidden=false;}}catch(err){$('#catalog-icon-error').textContent=err.message;}finally{iconPending=false;f.querySelector('[type=submit]').disabled=false;e.target.value='';}};$('#catalog-icon-remove').onclick=()=>{x.icon='';$('#catalog-icon-preview').innerHTML=catalogIcon(x,'catalog-icon-preview');$('#catalog-icon-kind').textContent='Стандартная иконка класса';$('#catalog-icon-remove').hidden=true;};function capture(){if(f.elements.perkRequirements){x.requirements=JSON.parse(f.elements.perkRequirements.value||'[]');x.repeatable=f.elements.perkRepeatable.checked;}const oldHacking=x.equipment?.hackingBonus;for(const k of ['displayName','subtype','manufacturer','description','rulesText'])x[k]=f.elements[k].value;const raw=f.elements.price.value;x.economy={currency:x.classId==='perk'?'xp':'eddies',price:raw===''?null:Number(raw)};x.price=x.classId==='perk'?undefined:x.economy.price;if(x.classId==='perk')x.cost=x.economy.price;x.archived=f.elements.archived.checked;x.startAllowed=!!f.elements.startAllowed?.checked;x.availability={...x.availability,startAllowed:x.startAllowed,restrictions:f.elements.restrictions.value};document.querySelectorAll('#catalog-form [data-typed]').forEach(el=>{x[el.dataset.store]??={};x[el.dataset.store][el.dataset.typed]=el.type==='checkbox'?el.checked:el.value===''?null:el.type==='number'?Number(el.value):el.value;});document.querySelectorAll('#catalog-form [data-effect]').forEach(row=>{const e=x.effects[+row.dataset.effect];row.querySelectorAll('[data-effect-field]').forEach(el=>{if(el.dataset.effectField!=='targetType'||e.type==='stat_modifier')e[el.dataset.effectField]=el.dataset.effectField==='value'?Number(el.value):el.value;});});if(x.classId==='neurodeck'){const bonus=x.equipment.hackingBonus,eff=x.effects.find(e=>e.type==='stat_modifier'&&e.targetType==='skill'&&e.targetId==='hacking'&&e.duration==='while_installed');if(bonus!==oldHacking&&bonus!=null){if(eff)eff.value=bonus;else x.effects.push({id:'stat-hacking',type:'stat_modifier',targetType:'skill',targetId:'hacking',value:bonus,duration:'while_installed',stackPolicy:'unique'});}else if(eff)x.equipment.hackingBonus=eff.value;}}
$('#catalog-cancel').onclick=()=>{editor.classList.remove('is-open');editor.innerHTML='<p class="hint">Выбери запись для редактирования</p>';};f.elements.classId.onchange=()=>{capture();x.classId=f.elements.classId.value;draw();};$('#effect-add').onclick=()=>{capture();x.effects.push({id:'effect-'+crypto.randomUUID(),type:'stat_modifier',targetType:'skill',targetId:'shooting',value:1,duration:x.classId==='perk'?'while_learned':x.classId==='clothing_armor'?'while_equipped':'while_installed',stackPolicy:'unique'});draw();};$('#derived-add').onclick=()=>{capture();x.effects.push({id:'effect-'+crypto.randomUUID(),type:'derived_modifier',targetId:'max_hp',value:1,duration:'while_installed',stackPolicy:'unique'});draw();};document.querySelectorAll('[data-effect-remove]').forEach(b=>b.onclick=()=>{capture();x.effects.splice(+b.dataset.effectRemove,1);draw();});document.querySelectorAll('[data-effect-field="targetType"]').forEach(el=>el.onchange=()=>{capture();const e=x.effects[+el.closest('[data-effect]').dataset.effect];e.targetId=e.targetType==='attribute'?'body':'brawling';draw();});f.onsubmit=async event=>{event.preventDefault();if(iconPending)return;try{capture();const cls=cv2().classes.find(c=>c.id===x.classId);if(!cls)throw Error('Выбери класс предмета');const cat=item&&!duplicate?item.cat:cls.legacyCategory;x.name=item&&!duplicate?item.name:x.displayName.trim();if(!x.name)throw Error('Укажи название');if((!item||duplicate)&&D.catalog[cat].some(i=>i.name===x.name))throw Error('Такое название уже существует');x.catalogId=x.catalogId||x.id||'custom:'+crypto.randomUUID();x.id=x.catalogId;const next=cv2().normalizeItem(x,cat);cv2().validateItem(next);if(next.startAllowed&&!ND_SHOP.allowed({...next,cat}))throw Error('Параметры не соответствуют стартовым ограничениям');const button=f.querySelector('[type=submit]');button.disabled=true;await persistCatalog(cat,x.name,next);showCatalogAdmin();}catch(e){$('#catalog-editor-error').textContent=e.message;const b=f.querySelector('[type=submit]');if(b)b.disabled=false;}};}
draw();editor.classList.add('is-open');editor.scrollIntoView({block:'nearest',behavior:'instant'});}

function startAvailabilityControl(cat,item){if(!portalMaster||cat==='perks')return '';return `<label class="start-availability"><input type="checkbox" data-start-availability="${esc(ND_SHOP.key(cat,item.name))}" ${item.startAllowed?'checked':''}><span>Доступен при стартовой закупке</span></label>`;}
document.addEventListener('change',async event=>{const input=event.target;if(!input.matches('[data-start-availability]'))return;if(!portalMaster){input.checked=!input.checked;return;}const desired=input.checked;input.disabled=true;try{const [cat,name]=JSON.parse(input.dataset.startAvailability),item=D.catalog[cat].find(x=>x.name===name);if(!item)throw Error('Предмет не найден');const next={...item,startAllowed:desired,availability:{...item.availability,startAllowed:desired}};if(desired&&!ND_SHOP.allowed({...next,cat}))throw Error('Сначала укажи базовую стоимость и проверь стартовые ограничения в редакторе предмета.');await persistCatalog(cat,name,next);document.querySelectorAll('[data-start-availability]').forEach(el=>{if(el.dataset.startAvailability===input.dataset.startAvailability)el.checked=desired;});notify(desired?'Предмет доступен при стартовой закупке':'Предмет убран из стартовой закупки');}catch(e){input.checked=!desired;notify(e.message);}finally{input.disabled=false;}});

const catalogDefaultIcons=Object.freeze({melee_weapon:'melee.webp',ranged_weapon:'ranged.webp',clothing_armor:'armor.webp',implant:'implant.webp',neurodeck:'neurodeck.webp',worm:'worm.webp',heavy_demon:'demon.webp',throwable:'grenade.webp',medicine:'medicine.webp',stimulant:'stimulant.webp',gadget:'gadget.webp',vehicle:'vehicle.webp',perk:'perk.svg'});
function hasCustomCatalogIcon(item){return typeof item?.icon==='string'&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(item.icon)&&item.icon.length<=60000;}
function defaultCatalogIcon(item,{manual=false}={}){return 'assets/item-icons/'+(manual?'manual.webp':(typeof item?.classId==='string'&&Object.hasOwn(catalogDefaultIcons,item.classId)?catalogDefaultIcons[item.classId]:'other.webp'));}
function catalogIconSource(item,options={}){return !options.manual&&hasCustomCatalogIcon(item)?item.icon:defaultCatalogIcon(item,options);}
function catalogIcon(item,cls='catalog-item-icon',options={}){return `<img class="${esc(cls)}" src="${esc(catalogIconSource(item,options))}" data-item-icon data-item-default="${defaultCatalogIcon(item,options)}" alt="" loading="lazy" decoding="async">`;}
// Error events do not bubble. A failed custom image falls back to its class,
// then to the universal asset, with a bounded final state if that also fails.
document.addEventListener('error',event=>{const img=event.target;if(!img?.matches?.('img[data-item-icon]'))return;const universal='assets/item-icons/other.webp',fallback=img.dataset.itemDefault;if(img.getAttribute('src')!==fallback&&!img.dataset.itemClassTried){img.dataset.itemClassTried='1';img.setAttribute('src',fallback);}else if(img.getAttribute('src')!==universal&&!img.dataset.itemUniversalTried){img.dataset.itemUniversalTried='1';img.setAttribute('src',universal);}else img.style.visibility='hidden';},true);
